        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>HAY</strong> properly so called, was not in use among the Hebrews; straw was used instead. They cut the grass green as it was needed. The word rendered “hay” in Proverbs 27:25 means the first shoots of the grass. In Isaiah 15:6 the Revised Version has correctly “grass,” where the Authorized Version has “hay.”",
